"""Write DRAFTS.md: every model-facing text of step 4, verbatim from prompts.py, hook.py and run_step2.py."""
import os
import sys

here = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, here)
sys.path.insert(0, os.path.join(os.path.dirname(here), "scripts"))
import hook  # noqa: E402
import prompts  # noqa: E402
import run_step2 as r  # noqa: E402

fmt = r.ONE_PASS + " " + r.ANSWER_FMT
parts = [
    "# Step 4: model-facing texts (DRAFT, for Zili Luo's approval)",
    "Generated by review_drafts.py from the code, so this is exactly what the agents see.",
    "## 1. Learning session prompt (3 independent sessions)", prompts.LEARN,
    "## 2. Learning / reconcile feedback (Stop hook, up to %d times)" % hook.MAX_ROUNDS,
    hook.LEARN_MSG + "\n\nReconcile adds: " + hook.RECON_EXTRA,
    "## 3. Reconcile session prompt", prompts.RECONCILE,
    "## 4. Test session prompt, arm G", r.TASK + " " + prompts.TEST + "\n\n" + fmt,
    "## 5. Test session Stop hook (once)", hook.TEST_MSG,
    "## 6. Arms N and P, for comparison",
    "N: " + r.TASK + " Answer the final query. " + fmt,
    "P: " + r.TASK + " " + r.PLAN_FIRST + " Answer the final query. " + fmt,
    "## 7. Framework documentation the agents read (gram/README.md)",
    open(os.path.join(here, "gram", "README.md"), encoding="utf-8").read(),
]
out = []
for p in parts:
    out.append(p if p.startswith("#") or p.startswith("Generated") else "\n".join("> " + l for l in p.split("\n")))
open(os.path.join(here, "DRAFTS.md"), "w", encoding="utf-8").write("\n\n".join(out) + "\n")
print("wrote DRAFTS.md")
